CONTENT_P6 = [
{"module": "快速入门", "articles": [
 {"title": "第一次登录后必做的十项设置", "url": "/help/getting-started/first-day-setup",
  "sections": [("首日设置清单", "首次登录后建议按以下清单完成基础设置，避免后续返工。第一，完善企业信息和本位币，影响后续所有财务数据。第二，邀请成员并按岗位分配角色，先把仓库、客服、运营账号开好。第三，完成第一个主力店铺授权并确认订单能同步进来。第四，配置仓库和库位，录入期初库存实数。第五，下载导入模板建立商品资料，完成平台SKU映射。第六，开通至少一个物流渠道并安装打印控件，用测试单走通打单。第七，配置库存同步频率和安全库存阈值。第八，设置自动审单规则，建议先只开地址和缺货校验。第九，配置预警通知接收人和企业微信机器人。第十，预约一次实施顾问的远程巡检，让顾问帮忙核对前面九项。全部完成通常需要半天到一天，完成后业务就具备了上线试运行条件。剩下的利润口径、头程分摊等财务设置可以在首月并行配置，不影响发货主链路。")]},
 {"title": "试运行阶段怎么验证系统", "url": "/help/getting-started/pilot",
  "sections": [("试运行验收方法", "建议用一周到两周做并行试运行，期间系统与原有操作方式同时进行，每天固定时间核对四类数据。订单核对：系统订单数与平台后台订单数逐笔对，重点看有没有漏单和状态不一致。库存核对：每天抽盘十个高频SKU，验证扣减和释放是否准确。发货核对：跟踪号回传后在平台后台确认状态已变更，记录回传耗时。财务核对：选十单有代表性的订单手工算一遍利润，与系统利润单逐项对比，确认费用口径。试运行中发现的问题分三类记录：配置错误（当场修正）、操作不熟（安排针对性培训）、疑似缺陷（提交工单跟踪）。连续三天四类数据全部核对一致、首单跑通且客服仓库能独立操作，就可以正式切换。切换当天建议选订单平淡的日子，保留旧系统只读权限一个月作为兜底。")]},
]},

{"module": "店铺授权", "articles": [
 {"title": "授权后第一天要检查什么", "url": "/help/auth/day-one-check",
  "sections": [("授权后检查清单", "店铺授权成功不等于万事大吉，第一天请逐项检查。订单：手动触发一次同步，确认近7天订单全部进入系统且数量与平台一致，抽查订单的金额、地址、商品明细字段完整。商品：确认在售Listing拉取成功，平台SKU与内部SKU自动匹配率符合预期，未匹配的列入映射计划。库存：确认库存推送开关按预期开启或关闭，多店铺共仓场景重点核对可售数计算。售后：确认退款和站内信权限生效，客服账号能看到会话。财务：结算报告和广告报告权限按需授权，确认能拉到最近一期账单。权限：确认子账号对该店铺的数据可见范围正确。最后在店铺管理记录授权时间和令牌到期日，把续期提醒指派给具体负责人。这一轮检查通常一小时内可以完成，但能避免上线后八成的低级问题。")]},
 {"title": "授权安全红线", "url": "/help/auth/security-redline",
  "sections": [("授权安全规范", "店铺授权涉及核心经营资产，必须遵守几条安全红线。第一，所有授权操作走系统内官方跳转，不要在任何第三方页面输入平台密码，云帆员工也永远不会索要密码。第二，主账号账号、密码、两步验证设备由企业可信人员集中保管，人员离职当天完成换绑和全部会话踢出。第三，不要把API密钥、密钥对截图发到公开群或工单中，密钥只配置在渠道页面的加密输入框里，怀疑泄露立即在平台后台作废并轮换。第四，代运营合作结束立即解除应用授权，不要只做口头约定。第五，定期（每季度）在店铺管理检查授权应用列表和登录记录，出现陌生应用或异地登录立即冻结排查。这些动作的操作成本很低，但能避免店铺被盗、数据泄露这类一旦发生就损失巨大的事故。")]},
]},

{"module": "商品与SKU", "articles": [
 {"title": "商品资料治理的五个习惯", "url": "/help/product/data-hygiene",
  "sections": [("资料治理习惯", "商品资料是订单、库存、财务三条链路的共同地基，建议养成五个治理习惯。第一，新品先在ERP建档再刊登，保证内部SKU和平台链接从第一天就打通，杜绝先卖后补。第二，重量尺寸按实测填写，影响运费试算和渠道选择，估填的数据会让利润单持续失真。第三，敏感属性（带电、液体、磁性、品牌授权）必填且如实维护，这是物流扣件和合规风险的根源字段。第四，每周跑一次映射体检，把未映射、错映射的链接在发错货之前修掉。第五，停用和停产商品定期清理，但保留编码不删除，历史订单和售后还要引用。资料治理不需要专门项目化，把这五个动作嵌入上新和周度运营例会的固定议程，一个月后数据质量就会有明显改善，后续所有报表的可信度都建立在这个基础上。")]},
]},

{"module": "订单管理", "articles": [
 {"title": "大促订单保障作战清单", "url": "/help/orders/peak-checklist",
  "sections": [("大促保障清单", "大促前两周开始按清单准备。订单侧：复盘上一届大促的同步延迟峰值和异常单类型，提前调整审单规则阈值；与平台确认活动订单、预售订单的特殊状态；清理积压异常单和超过48小时的预占单。库存侧：完成盘点，锁定主力商品库存数；核对安全库存和自动下架策略；与供应商确认应急补货交期。物流侧：与主力渠道锁定运力并确认大促揽收安排；配置备选渠道和自动降级规则；测试批量打单每批的数量上限。人员侧：制定排班表，明确异常单、客服、打单三个岗位的值班人和升级路径；客服话术和留言模板提前更新。系统侧：预约云帆大促压测并关注维护公告。大促中每天早晚两次复盘积压量和失败队列，大促后输出履约时效、超卖、异常成本复盘报告，沉淀为下一届的改进项。")]},
 {"title": "订单数据字段字典（核心）", "url": "/help/orders/field-dictionary",
  "sections": [("核心字段口径", "订单数据常用字段口径如下。下单时间为买家在平台完成下单的时间（站点时区）；付款时间为平台确认收到款项的时间，业务统计以付款时间为准。订单金额为商品成交金额，不含买家付运费；平台佣金和费用在财务数据中单独体现。订单状态以平台状态加内部履约状态双轨展示，二者冲突时以平台状态为准并生成异常提醒。预占库存数在订单进入系统时计算，等于订单商品行数量之和，取消和拆单都会联动调整。异常标签由审单规则产生，可叠加多个。买家留言仅包含下单时备注，聊天消息在客服模块。店铺、平台、站点、仓库、物流渠道、负责运营都是订单上的归属维度，报表按这些维度汇总。导出和自定义报表的指标口径与页面完全一致，具体公式可在指标说明中查看。")]},
]},

{"module": "物流发货", "articles": [
 {"title": "物流商选择评估框架", "url": "/help/logistics/vendor-evaluation",
  "sections": [("渠道评估方法", "选择物流商不要只比价，建议用五维框架季度评估。价格维度：首重续重、附加费、旺季加价，用真实历史订单批量试算而不是报价表单价。时效维度：揽收时长、在途时长、签收稳定性，系统看板按目的国给出实际数据。可靠性维度：回传成功率、轨迹完整率、丢件率和破损率，丢件率超过1%要重点警惕。服务维度：查件响应速度、理赔顺畅度、系统对接成熟度，理赔拖延的低价渠道最终不省钱。弹性维度：大促期间能否保证揽收和舱位。建议主力渠道保留两家形成竞争，按目的国分配份额；每季度用系统导出的考核数据与物流商谈判，把SLA写进合作协议。新渠道先给10%订单试跑一个月，数据达标再放量，避免一次性切换导致大面积时效事故。")]},
 {"title": "打单发货SOP（标准作业程序）", "url": "/help/logistics/sop",
  "sections": [("仓库发货SOP", "标准打单发货流程建议固化为八步。第一步，打单员在待发货池按波次筛选订单（建议按渠道和国别分波次）。第二步，系统校验库存和异常标签，异常单自动剔除并提示原因。第三步，批量申请跟踪号并打印面单和拣货单，面单与拣货单批次号一致。第四步，拣货员按拣货单库位路径取货，PDA扫码确认SKU和数量。第五步，复核台二次扫码核对，防止错发漏发，多品订单逐件核对。第六步，打包、称重（建议留痕称重照片）、贴面单。第七步，点击确认交运，已对接渠道等待揽收回传，手工渠道确认交货后手动回传。第八步，交接物流商并签字或扫码交接，留底交接清单。全程做到单、货、面单三者绑定，任何一步发现不符立即挂起处理，不要带着异常流到下一步。这个SOP配合系统记录，错发率可稳定控制在万分之几。")]},
]},

{"module": "库存管理", "articles": [
 {"title": "库存管理周度巡检表", "url": "/help/inventory/weekly-check",
  "sections": [("周度巡检内容", "建议每周固定一次库存巡检，半小时内可完成。一看断货预警清单：低于安全库存的SKU是否都已生成采购或调拨动作，红色零库存项是否有在途。二看可售数异常：负库存必须当天查明原因，不允许过夜。三看库存对账差异：与平台快照不一致的SKU逐笔确认推送日志。四看呆滞库存：库龄超过90天的清单和金额变化，推动清仓计划。五看在途异常：超过正常交期未到货的采购单和长时间未收货的调拨单。六看盘点差异：本周盘盈亏的Top SKU和差异率趋势。巡检结论用一页记录：问题、责任人、截止时间，下周先回顾上周遗留。把巡检数据与采购、运营的周会绑定，库存问题就不再是月底对账时才爆出来的意外，而是每周都在收敛的例行管理动作。")]},
 {"title": "海外仓库存管理要点", "url": "/help/inventory/overseas-warehouse",
  "sections": [("海外仓管理要点", "海外仓管理比国内仓多出三个控制点。补货控制：头程在途长（海运30到45天），补货决策要基于销量预测而非当前库存，系统用日均销量、在途量、头程天数计算建议发货日，断货风险提前一个月就要行动。库龄控制：海外仓储费随库龄阶梯上涨，超过一年的呆滞货可能被收高额长期费甚至要求弃置，建议90天不动销即启动折扣清仓，180天前必须处理完毕。数据一致性：海外仓库存以WMS回传为准，日结对账差异要在48小时内查明，常见原因是已发未回传、退件未上架、仓内损耗。选仓阶段关注仓的API对接能力，不能实时回传库存和订单状态的仓库，系统再强也管不准。")]},
]},

{"module": "采购与供应商", "articles": [
 {"title": "大促备货计划怎么做", "url": "/help/purchase/peak-stocking",
  "sections": [("备货计划流程", "大促备货按四步走。第一步销售预测：运营按历史大促增幅、活动资源位、广告计划给出每个SKU的目标销量，而不是简单用日均销量乘天数。第二步库存缺口计算：目标销量加安全库存，减去现有可用库存和已在途库存，得出备货量；采购周期长的海运商品倒排时间，至少提前60天下单。第三步风险分摊：核心款备货足，长尾款保守，与供应商谈好大促期间的加急补货条款和滞销退换约定，必要时部分销量用空运快补兜底。第四步执行跟踪：备货计划在系统中锁定，采购单、头程单、入库进度逐周跟踪，大促前两周所有主力SKU必须完成到仓。大促后复盘备货准确率，区分缺货损失和呆滞损失，持续校准预测模型。")]},
]},

{"module": "客服售后", "articles": [
 {"title": "客服团队排班与SLA管理", "url": "/help/service/scheduling",
  "sections": [("排班与SLA落地", "客服排班要覆盖平台买家活跃时段而不是只按本地工作时间：欧美站点订单集中在北京时间下午和晚间，建议安排晚班到23点；周末保留值班处理发货前的改地址、取消请求，这些请求错过时点就会变成退货损失。班次衔接时使用会话交接备注，未结束的纠纷单必须写清当前状态和下一步承诺。SLA管理建议盯住三个指标：首次响应时长（平台考核项，设硬上限）、纠纷24小时响应率、退款处理时长。每天早会看前一天三个指标的超时清单找原因，而不是月底看平均数。旺季前用历史会话量预估人力缺口，临时客服提前两周培训，只让其处理标准场景，复杂售后由资深客服兜底。AI助手承担常见问题后，人力可以集中到纠纷挽回等高价值动作。")]},
 {"title": "售后成本分析与改进", "url": "/help/service/cost-analysis",
  "sections": [("售后成本归因", "售后不是纯成本中心，售后数据是产品和履约改进的输入。每月把售后成本按原因结构拆开：物流原因（丢件、破损、超时）对应物流商考核和更换；质量原因对应供应商索赔和选品淘汰；描述不符对应刊登内容和图片准确性；客服沟通失误对应培训和话术问题；买家原因（拍错、不想要）计入正常退款率。每类成本都算到金额而不只是单量，一单补发可能同时损失商品和两程运费。改进动作设定责任部门和目标值，下月售后会先回顾上月动作效果。退款率、纠纷率、差评率按SKU和运营归集后，经常能发现个别问题商品贡献了大部分售后量，集中处理少数SKU就能显著降低售后总成本。")]},
]},

{"module": "财务对账", "articles": [
 {"title": "财务上线首月怎么校准口径", "url": "/help/finance/first-month",
  "sections": [("口径校准方法", "财务模块上线首月不要直接信报表，用平行账校准。选一个完整月份，系统报表与会计手工账并行。第一周先对齐收入：平台结算单逐单与订单匹配，差异分类为跨期、退款、汇差、未识别费用。第二周对齐成本：确认采购入库价、头程分摊、移动加权结转与手工成本表一致，差异通常出在头程口径。第三周对齐费用：广告费取数窗口、物流费账单实际结算价、包材和人工等线下费用是否录入。月末出差异调节表，目标是差异率降到0.5%以内。每发现一项差异就固定一条口径规则并写进口径说明文档。第二个月起报表可以直接用于经营决策，但每月结账仍保留差异调节表存档。口径校准的价值在于让运营看到的利润和老板看到的钱是同一套数字。")]},
 {"title": "业财一体化的数据流转", "url": "/help/finance/data-flow",
  "sections": [("业财流转链路", "理解数据怎么从业务流到财务，能解释八成对账疑问。订单付款形成应收和收入；发货出库按移动加权成本结转销售成本；物流下单形成对物流商的应付（实际账单回来后调整）；采购入库形成存货和对供应商应付；头程费用分摊进入存货成本；平台结算单把佣金、广告费、退款、罚款逐单归集；最终每笔订单产出一张利润单，按月汇总成利润表。这条链路上的每个数字都能从报表下钻到业务单据再到原始凭证。财务不要在业务系统外另建一套Excel台账，两套数据必然越走越远，正确做法是业务在系统内留痕、财务在系统内调账，差异通过调节表管理。理解这条链路后，运营也能明白自己的动作（改价、选渠道、备货）最终如何影响净利润。")]},
]},

{"module": "刊登与商品发布", "articles": [
 {"title": "新品上架SOP", "url": "/help/listing/new-product-sop",
  "sections": [("新品上架流程", "标准新品上架建议七步走。第一步，ERP内建档：录入SKU、重量尺寸、成本、敏感属性和申报要素。第二步，准备素材：主图、详情图、视频和多语言文案集中存放，品牌商品确认授权资料齐备。第三步，采集或新建刊登任务，选择目标平台店铺和类目，完成类目映射。第四步，填写变体矩阵，每个子规格绑定对应系统SKU，价格按定价公式自动带出后人工确认。第五步，跑合规预检，处理全部禁词、属性、图片问题。第六步，设置库存推送策略（新品建议小批量库存试水）和定时刊登时间。第七步，上架后监控：48小时内确认链接在售可售、库存数正确，7天后看曝光点击数据决定是否开广告。每一步在系统留痕，新品资料沉淀为模板，后续同品类上架时间可缩短一半以上。")]},
]},

{"module": "数据报表", "articles": [
 {"title": "经营周会数据看板怎么搭", "url": "/help/reports/weekly-dashboard",
  "sections": [("周会看板设计", "经营周会建议固定一页看板，六个模块足够。销售模块：本周GMV、订单量、客单价及环比。利润模块：毛利额、毛利率、费用结构异常项。库存模块：断货SKU数、呆滞金额、周转天数。履约模块：平均发货时长、回传成功率、物流超时率。客服模块：首次响应时长、退款率、新增纠纷。预警模块：红色待办、超期未处理工单、即将到期授权。每个指标只保留一个统一口径并标注责任人，避免会上争论数字。数据周一看上周，周二各部门出改进动作，周五前更新进展。指标不在多而在连续跟踪，连续看三个月环比趋势比一次性拉几十个维度更有决策价值。自定义报表搭建好后订阅定时推送，周一早上自动发到管理群，会议直接讨论动作而不是等数据。")]},
]},

{"module": "账号与权限", "articles": [
 {"title": "员工入转调离权限流程", "url": "/help/admin/lifecycle",
  "sections": [("账号生命周期管理", "把账号管理嵌入HR流程能堵住大部分安全漏洞。入职：HR发起开号申请，按岗位模板分配角色和店铺范围，第一天完成安全培训和二次验证绑定。转岗：权限不自动叠加，按新岗位重新授权并收回原岗位权限，避免权限滚雪球式积累。兼职或借调：用临时权限并设置到期自动回收。晋升：增加审批权限时同步增加操作日志审查范围。离职：确定离职日期后系统账号先降级再在最后工作日停用，当日踢出全部会话，交接其负责的店铺、采购单和未结工单；API密钥和平台主账号同步换绑。每季度做一次全员权限复核，由部门负责人确认名单。账号生命周期管理不需要复杂工具，关键是开号、变更、停号三个节点都有系统流程而不是靠口头通知。")]},
]},

{"module": "常见报错与故障处理", "articles": [
 {"title": "故障期间如何保证发货不停", "url": "/help/errors/business-continuity",
  "sections": [("业务连续性预案", "系统或平台故障期间，保障发货的核心思路是用离线方式维持主链路。提前准备：导出当日待发货订单清单（含收件信息和SKU）作为应急底单；物流商后台保留独立下单打单能力，知道如何在渠道后台手工操作；面单模板和报关资料有本地备份。故障时按预案执行：仓库用导出的清单拣货打包，在物流商后台直接下单打印；订单状态、跟踪号先记录在应急登记表，不强行在系统里操作。恢复后由专人把应急期间的跟踪号批量导回系统（支持Excel批量补录），系统自动完成回传和扣库存核销，避免重复单。预案每半年演练一次，让仓库和客服真的走一遍流程。大促前一周必须确认应急清单的导出权限和负责人，故障不可怕，没有准备的故障才会演变成大面积迟发。")]},
 {"title": "如何向技术支持提供有效信息", "url": "/help/errors/effective-report",
  "sections": [("报障信息规范", "技术支持定位问题依赖完整信息，报障时按这个模板提供能把解决时间缩短一半以上。账号与环境：登录账号、浏览器版本、是否无痕模式复现。问题对象：具体订单号、SKU、店铺、物流渠道或工单号，不要只说“有个订单有问题”。时间点：问题发生的准确时间，最好精确到分钟，后台日志按时间检索。复现路径：从哪个页面点了什么按钮，每一步操作和期望结果。实际结果：完整报错截图，包含地址栏、错误码、错误编号和页面全部内容，不要只截弹窗一角。影响范围：多少订单、哪些店铺、是否所有同事都复现。已尝试动作：清缓存、换浏览器、重跑任务等，避免支持重复指引。一个工单聚焦一个问题，多个问题分开提交。")]},
]},

{"module": "套餐与计费", "articles": [
 {"title": "投入产出（ROI）怎么算", "url": "/help/pricing/roi",
  "sections": [("ROI测算方法", "判断系统投入是否划算，建议把收益拆成四类量化。人力节省：订单处理、打单、对账、报表占用的工时，按当地人力成本折算，多数中型团队在录入、对账两项就能省出1到2个人。损失减少：超卖罚款、漏单损失、丢件赔付、迟发罚款，用上线前三个月的实际发生额对比。库存改善：周转天数下降释放的占用资金，库存准确率提升减少的呆滞跌价，这部分金额往往最大但最容易被忽略。增长支撑：多平台扩张时不需要等比例增加人力。把四类年化收益加总与年费对比，中型卖家通常在系统上线后3到6个月收回当年成本。测算数据可以直接从系统报表取，建议上线满3个月时正式复盘一次ROI，作为续约和模块增购的决策依据，也可以让客户成功经理协助拉取所需数据。")]},
]},

{"module": "客户支持服务", "articles": [
 {"title": "大促期间支持服务怎么用", "url": "/help/support/peak-support",
  "sections": [("大促支持资源", "大促期间（平台大促日及前后各两天）支持体系全面升级。值守时间：技术支持7乘24小时在线，企业群内值班工程师实时响应；客户成功经理在线答疑和配置调整指导；实施团队协助应急配置。响应优先级：核心链路阻断（无法同步、无法打单、回传大面积失败）按P1处理，30分钟内响应；大促期间建议企业内部指定一名对接人统一报障，避免多人重复咨询淹没紧急问题。提前动作：大促前45天预约压测、前14天完成规则和库存配置复核、前7天确认全员知道应急流程和值班群入口。非紧急的报表和配置需求建议大促后再提，把通道让给发货阻断类问题。大促后主动申请故障时间线和数据复盘，用于向平台申请考核豁免和内部复盘改进。")]},
]},
]
